...
15	  }
16	}
17	
18	/** Whether a word is a usable task name. */
19	function isName(word) {
20	  return NAME.test(word)
21	}
22	
23	/** Whether a word is a usable workspace path. */
24	function isPath(word) {
25	  return PATH.test(word) && !word.startsWith('/') && !word.split('/').includes('..')
26	}
27	
28	/**
29	 * Every input line, with the empty tail a trailing newline leaves dropped.
30	 * @param {string} text - the whole input.
31	 * @returns {string[]} the lines.
32	 */
33	export function splitLines(text) {
34	  const split = text.split('\n')
35	  if (split.length > 0 && split[split.length - 1] === '') split.pop()
36	  return split
37	}
38	
39	/** The field a directive attaches to, and the word the usage line names. */
40	const ATTACHING = new Map([
41	  ['needs', { field: 'needs', word: 'dependency' }],
42	  ['reads', { field: 'reads', word: 'path' }],
43	  ['writes', { field: 'writes', word: 'path' }],
44	])
45	
46	/**
47	 * Parse a task file into its tasks.
48	 * @param {string[]} lines - the input lines.
49	 * @returns {Map<string, {name: string, command: string, needs: string[], reads: string[], writes: string[]}>} the tasks by name, in declaration order.
50	 */
51	export function parse(lines) {
52	  const tasks = new Map()
53	  const referenced = []
54	  const attachments = []
55	  for (const [index, raw] of lines.entries()) {
56	    const line = index + 1
57	    const text = raw.trim()
58	    if (text === '' || text.startsWith('#')) continue
59	    const words = text.split(/\s+/u)
60	    const attaching = ATTACHING.get(words[0])
61	    if (words[0] === 'task') {
62	      if (words.length < 3) throw new ParseError(line, 'expected task <name> <word>...')
63	      const name = words[1]
64	      if (!isName(name)) throw new ParseError(line, `invalid task name ${name}`)
65	      if (tasks.has(name)) throw new ParseError(line, `task ${name} is declared twice`)
66	      tasks.set(name, { name, command: words.slice(2).join(' '), needs: [], reads: [], writes: [] })
67	    } else if (attaching !== undefined) {
68	      if (words.length < 3) throw new ParseError(line, `expected ${words[0]} <name> <${attaching.word}>...`)
69	      const [, name, ...values] = words
70	      if (!isName(name)) throw new ParseError(line, `invalid task name ${name}`)
71	      referenced.push(name)
72	      for (const value of values) {
73	        if (attaching.field === 'needs') {
74	          if (!isName(value)) throw new ParseError(line, `invalid task name ${value}`)
75	          referenced.push(value)
76	        } else if (!isPath(value)) {
77	          throw new ParseError(line, `invalid path ${value}`)
78	        }
79	      }
80	      attachments.push({ name, field: attaching.field, values })
81	    } else {
82	      throw new ParseError(line, `unknown directive ${words[0]}`)
83	    }
84	  }
85	  for (const name of referenced) {
86	    if (!tasks.has(name)) throw new ParseError(0, `unknown task ${name}`)
87	  }
88	  for (const { name, field, values } of attachments) {
89	    const list = tasks.get(name)[field]
90	    for (const value of values) {
91	      if (!list.includes(value)) list.push(value)
92	    }
93	  }
94	  return tasks
95	}

