2	/** The command: `order`, `show <name>`, `files <name>`, `digest <path>...` and `plan <snapshot>`. */
3	
4	import { existsSync, readFileSync } from 'node:fs'
5	import { digestBytes } from './digest.js'
6	import { CycleError, order } from './graph.js'
7	import { parse, ParseError, splitLines } from './parse.js'
8	import { plan, readSnapshot, SnapshotError } from './plan.js'
9	
10	const USAGE = 'usage: cli.js order|show <name>|files <name>|digest <path>...|plan <snapshot>'
11	
12	/** Report one failure the way the specification words it, and stop. */
13	function fail(message, code = 2) {
14	  process.stderr.write(`error: ${message}\n`)
15	  process.exit(code)
16	}
17	
18	/** One `files` field, with `-` standing for an empty list. */
19	function field(label, values) {
20	  return `${label}: ${values.length === 0 ? '-' : [...values].sort().join(' ')}`
21	}
22	
23	const argv = process.argv.slice(2)
24	const mode = argv[0]
25	const arity = { order: 1, show: 2, files: 2, plan: 2 }
26	if (mode === 'digest' ? argv.length < 2 : argv.length !== arity[mode]) fail(USAGE)
27	
28	let tasks
29	try {
30	  tasks = parse(splitLines(readFileSync(0, 'utf8')))
31	} catch (error) {
32	  if (!(error instanceof ParseError)) throw error
33	  fail(error.line === 0 ? error.message : `line ${error.line}: ${error.message}`)
34	}
35	
36	/** The named task, or the failure that names it. */
37	function named(name) {
38	  const task = tasks.get(name)
39	  if (task === undefined) fail(`unknown task ${name}`)
40	  return task
41	}
42	
43	const out = []
44	try {
45	  if (mode === 'order') {
46	    for (const name of order(tasks)) out.push(name)
47	  } else if (mode === 'show') {
48	    const task = named(argv[1])
49	    out.push(`${task.name}: ${task.command}`)
50	    out.push(field('needs', task.needs))
51	  } else if (mode === 'files') {
52	    const task = named(argv[1])
53	    out.push(field('reads', task.reads))
54	    out.push(field('writes', task.writes))
55	  } else if (mode === 'digest') {
56	    for (const path of argv.slice(1)) {
57	      out.push(`${path} ${existsSync(path) ? digestBytes(readFileSync(path)) : 'missing'}`)
58	    }
59	  } else {
60	    const decisions = plan(tasks, readSnapshot(argv[1]))
61	    for (const { name, reason } of decisions) out.push(reason === undefined ? `skip ${name}` : `run ${name} ${reason}`)
62	    const running = decisions.filter(decision => decision.reason !== undefined).length
63	    out.push(`total run=${running} skip=${decisions.length - running}`)
64	  }
65	} catch (error) {
66	  if (error instanceof CycleError) fail(error.message, 3)
67	  if (error instanceof SnapshotError) fail(error.message)
68	  throw error
69	}
70	process.stdout.write(out.map(line => `${line}\n`).join(''))

